import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.CDU0sSpB.js";const A=JSON.parse('{"title":"Day04 · 运行时就位","description":"","frontmatter":{"title":"Day04 · 运行时就位","outline":false},"headers":[],"relativePath":"log/day-04.md","filePath":"log/day-04.md","lastUpdated":null}'),a={name:"log/day-04.md"};function c(n,t,i,l,s,u){return e(),o("div",null,[...t[0]||(t[0]=[r('<p>2026-11-06 是 Hearth 从“阶段一 MVP”扩展到完整本机 Agent OS 的一天。当天 102 次提交涉及 432 个文件（+35,228/−4,327），把聊天优先界面、原生 Agent Runtime、四协议模型接入、来源与文档处理、本地发件箱、Windows 桌面助手、主动服务、记忆、方法进化、增量同步、租约、kill switch、加密备份、健康维护和脱敏诊断全部落到了可运行代码与自动测试中。</p><p>这一天没有用“页面存在”代替闭环：服务端、API、投影、执行器边界和测试一起提交。测试从 51 项扩展到 40 个测试文件、198 个测试；<code>npm run typecheck</code>、<code>npm run build</code> 和 <code>npm run docs:build</code> 均通过。阶段二至六仍然只算部分完成，原因不是代码没写，而是还缺真实账户、真实设备和长期运行验收。</p><h2 id="当天完成的能力" tabindex="-1">当天完成的能力 <a class="header-anchor" href="#当天完成的能力" aria-label="Permalink to &quot;当天完成的能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方向</th><th>结果</th></tr></thead><tbody><tr><td>聊天优先界面</td><td>重建 Web 为对话式入口，任务、提案、审批和产物围绕对话组织</td></tr><tr><td>原生 Agent Runtime</td><td>单 Agent 工具循环、四类预算、工具权限、检查点、等待输入与恢复、缺失产物补交</td></tr><tr><td>四协议模型</td><td>OpenAI Chat、OpenAI Responses、Anthropic Messages、Gemini 统一为流式 Agent 回合</td></tr><tr><td>双执行器</td><td><code>native</code> 与 <code>codex</code> 并列，执行器身份写入运行清单，失败不静默切换</td></tr><tr><td>来源与文档</td><td>本地文件、知识库、网页、TXT/Markdown/CSV/JSON/HTML/PDF/DOCX/XLSX 提取与来源条目</td></tr><tr><td>本地发件箱</td><td>草稿、一次性审批、批准后写入本机 outbox 并保存回执</td></tr><tr><td>Windows 桌面</td><td>六位配对、逐项能力审批、观察、暂停/接管/交还、低风险输入、UIA invoke 与 UWP 窗口归属</td></tr><tr><td>主动服务</td><td>六类触发器、主动收件箱、接受/忽略/稍后/转任务、注意力预算</td></tr><tr><td>记忆与方法</td><td>记忆候选/召回/纠正/冲突/遗忘/导出；方法候选、试跑证据、评估、晋升、拒绝、回退</td></tr><tr><td>多设备与安全</td><td>事件增量同步、对端认证、任务租约与 epoch fencing、设备撤销、令牌轮换、全局 kill switch</td></tr><tr><td>备份与运维</td><td>AES-256-GCM 加密备份、回滚式恢复、健康快照、周期维护、脱敏诊断</td></tr></tbody></table><h2 id="验证基线" tabindex="-1">验证基线 <a class="header-anchor" href="#验证基线" aria-label="Permalink to &quot;验证基线&quot;">​</a></h2><table tabindex="0"><thead><tr><th>检查项</th><th>结果</th></tr></thead><tbody><tr><td>测试</td><td><code>npm test</code> 通过 40 个测试文件、198 个测试</td></tr><tr><td>类型</td><td><code>npm run typecheck</code> 通过</td></tr><tr><td>Web 构建</td><td><code>npm run build</code> 通过</td></tr><tr><td>文档构建</td><td><code>npm run docs:build</code> 通过</td></tr><tr><td>真实任务</td><td>沿用阶段一验收：15 项全部执行，13 项通过；T07/T08 边界未改写</td></tr><tr><td>证据原则</td><td>没有把代码闭环写成真实验收，没有把外部评论或桌面动作写成已完成</td></tr></tbody></table><blockquote><p>本日志记录实现与内部验证，不代表 v1.0 发布。阶段二至六的真实账户、真实设备、长期运行和失败演练仍以<a href="https://hearthproject.github.io/hearth-os/delivery/capabilities.html" target="_blank" rel="noreferrer">能力状态</a>为准。</p></blockquote><h2 id="提交记录" tabindex="-1">提交记录 <a class="header-anchor" href="#提交记录" aria-label="Permalink to &quot;提交记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Commit</th><th>作者</th><th>具体修改</th></tr></thead><tbody><tr><td><code>a0544fd</code></td><td>JasonBuildAI</td><td>增加 Simple Pro 读模型，为后续聊天优先界面准备任务、审批和产物的聚合视图；8 个文件（+729/−21）。</td></tr><tr><td><code>b748d02</code></td><td>JasonBuildAI</td><td>将界面收敛为 Simple Pro 结构，删除旧的复杂控制面布局；32 个文件（+2,970/−1,360）。</td></tr><tr><td><code>3aca641</code></td><td>JasonBuildAI</td><td>把 Web 重建为聊天优先界面，围绕对话组织任务、提案和审批；9 个文件（+1,288/−357）。</td></tr><tr><td><code>8d28901</code></td><td>JasonBuildAI</td><td>加入来源注册表存储，记录来源类型、状态、读取时间和错误；3 个文件（+198/−1）。</td></tr><tr><td><code>cec6d41</code></td><td>JasonBuildAI</td><td>加入来源读取 API，支持本地文件、知识库和网页来源的读取与增量更新；5 个文件（+735/−2）。</td></tr><tr><td><code>b408eb3</code></td><td>JasonBuildAI</td><td>加入文档提取：TXT、Markdown、CSV、JSON、HTML、PDF、DOCX、XLSX 与页码/工作表/范围记录；6 个文件（+3,461/−74）。</td></tr><tr><td><code>d458bd3</code></td><td>JasonBuildAI</td><td>在新任务界面加入来源选择器，把已就绪来源条目附到任务；4 个文件（+180/−6）。</td></tr><tr><td><code>ae5bf0f</code></td><td>JasonBuildAI</td><td>增加发件箱草稿投影，展示草稿、提交状态和回执；3 个文件（+152/−2）。</td></tr><tr><td><code>b820dca</code></td><td>JasonBuildAI</td><td>加入发件箱草稿 API，支持编辑、保存、丢弃和提交审批；6 个文件（+551/−1）。</td></tr><tr><td><code>f1558a9</code></td><td>JasonBuildAI</td><td>批准后写入本地发件箱并保存回执，拒绝或失效同步草稿状态；4 个文件（+408/−4）。</td></tr><tr><td><code>5b6e50f</code></td><td>JasonBuildAI</td><td>加入 Windows 桌面助手，支持窗口观察、聚焦、点击、文本输入、按键和 UIA 动作；1 个文件（+358）。</td></tr><tr><td><code>34877a0</code></td><td>JasonBuildAI</td><td>把观察帧绑定到目标应用，拒绝把宿主窗口静默当成批准应用；3 个文件（+92/−15）。</td></tr><tr><td><code>97d0f07</code></td><td>JasonBuildAI</td><td>解析 UWP 宿主窗口的 UIA 子进程并映射到批准应用，例如 CalculatorApp → calculator；1 个文件（+109/−17）。</td></tr><tr><td><code>119b67f</code></td><td>JasonBuildAI</td><td>记录 UWP 与 UIA 的隔离验证结果，包括计算器 invoke 与观察→动作→自动观察链路；2 个文件（+6/−6）。</td></tr><tr><td><code>11a1e60</code></td><td>JasonBuildAI</td><td>加入主动触发引擎，覆盖截止窗口、失败/可恢复、结果不确定、审批等待、新来源和队列积压六类触发器；5 个文件（+1,144/−1）。</td></tr><tr><td><code>66ee76c</code></td><td>JasonBuildAI</td><td>加入主动收件箱与注意力预算，支持接受、忽略、稍后提醒和转任务；8 个文件（+624/−1）。</td></tr><tr><td><code>21d1592</code></td><td>JasonBuildAI</td><td>加入记忆核心与召回，记录来源、置信度、敏感度、版本和召回审计；7 个文件（+1,170/−3）。</td></tr><tr><td><code>ac92758</code></td><td>JasonBuildAI</td><td>加入记忆浏览、纠正、冲突和遗忘，遗忘时脱敏历史版本与召回审计；6 个文件（+599/−1）。</td></tr><tr><td><code>11b0307</code></td><td>JasonBuildAI</td><td>增加记忆投毒边界测试，确保记忆不能作为指令扩大权限；1 个文件（+21）。</td></tr><tr><td><code>b6b3f63</code></td><td>JasonBuildAI</td><td>加入方法评估引擎，记录基线/试跑成功率、耗时、token 和审批次数；5 个文件（+788）。</td></tr><tr><td><code>0e3a35f</code></td><td>JasonBuildAI</td><td>加入方法进化浏览，支持候选生成、评估、晋升、拒绝和回退；6 个文件（+493/−1）。</td></tr><tr><td><code>724e784</code></td><td>JasonBuildAI</td><td>加入事件增量同步与对端认证，按序号拉取、去重并重建投影；7 个文件（+816/−5）。</td></tr><tr><td><code>24c2ea4</code></td><td>JasonBuildAI</td><td>用 TTL、owner 和 epoch 为任务执行加租约，过期接管推进 epoch，旧 owner 提交被拒绝；7 个文件（+391/−7）。</td></tr><tr><td><code>e70b0d3</code></td><td>JasonBuildAI</td><td>加入全局 kill switch、设备撤销、令牌轮换和安全审计；14 个文件（+678/−22）。</td></tr><tr><td><code>44f58b9</code></td><td>JasonBuildAI</td><td>加入 AES-256-GCM 加密备份与回滚式恢复，校验 schema、user_version 和 integrity_check；16 个文件（+1,160/−22）。</td></tr><tr><td><code>b3cffeb</code></td><td>JasonBuildAI</td><td>加入运行健康快照、周期维护和脱敏诊断，维护失败标记 degraded；15 个文件（+974/−29）。</td></tr><tr><td><code>42d8827</code></td><td>JasonBuildAI</td><td>记录阶段四至六交付状态，明确已实现、已验证和留空项；13 个文件（+124/−12）。</td></tr><tr><td><code>32f0b0d</code></td><td>JasonBuildAI</td><td>统一四种模型协议，支持 OpenAI Chat、OpenAI Responses、Anthropic Messages 和 Gemini；5 个文件（+665/−74）。</td></tr><tr><td><code>581bc44</code></td><td>JasonBuildAI</td><td>聊天先回答材料问题，而不是把所有输入都直接派成任务；3 个文件（+61/−19）。</td></tr><tr><td><code>e4eefbb</code></td><td>JasonBuildAI</td><td>加入带预算和检查点的单 Agent 循环；5 个文件（+396）。</td></tr><tr><td><code>99392ea</code></td><td>JasonBuildAI</td><td>加入受权限约束的内置工具，覆盖读写、搜索、命令、联网、提问和完成；2 个文件（+589）。</td></tr><tr><td><code>9a37e78</code></td><td>JasonBuildAI</td><td>增加执行器、权限、预算和检查点契约；1 个文件（+58）。</td></tr><tr><td><code>375ff8d</code></td><td>JasonBuildAI</td><td>增加执行器注册表，让 native 与 codex 并列可选；1 个文件（+33）。</td></tr><tr><td><code>bbbbfab</code></td><td>JasonBuildAI</td><td>加入原生 Agent 执行器适配器，把 Runtime 接到调度器；3 个文件（+168）。</td></tr><tr><td><code>5f5009a</code></td><td>JasonBuildAI</td><td>需要联网或工程工作区权限的任务先在聊天中生成提案，确认后才派发；2 个文件（+79/−5）。</td></tr><tr><td><code>6b4295d</code></td><td>JasonBuildAI</td><td>任务等待输入时在界面内直接收集回答并继续执行；2 个文件（+53/−4）。</td></tr><tr><td><code>c776d2c</code></td><td>JasonBuildAI</td><td>记录原生运行时闭环，说明执行器、协议、工具、预算和恢复边界；2 个文件（+24/−2）。</td></tr><tr><td><code>b5a785f</code></td><td>JasonBuildAI</td><td>让健康检查从当前 schema 版本推导期望值，避免版本升级后测试漂移；2 个文件（+4/−4）。</td></tr></tbody></table><h2 id="边界与下一步" tabindex="-1">边界与下一步 <a class="header-anchor" href="#边界与下一步" aria-label="Permalink to &quot;边界与下一步&quot;">​</a></h2><ul><li>阶段二至六的代码闭环已经可运行，但真实邮件/日历、桌面高风险动作、手机入口、记忆生产对照、双设备切换和长期运行仍未验收。</li><li>当前聊天优先主导航只暴露聊天、任务、设备、设置；记忆、方法、同步、安全和运维已有 API 与页面组件，尚未全部接回主导航。</li><li>下一阶段不继续铺页面，而是按<a href="https://hearthproject.github.io/hearth-os/delivery/roadmap.html" target="_blank" rel="noreferrer">剩余路线</a>逐项补真实证据。</li></ul>',11)])])}const b=d(a,[["render",c]]);export{A as __pageData,b as default};
